/* Texture wrap modes */
#define G_TX_NOMIRROR       0
#define G_TX_WRAP           0
#define G_TX_MIRROR         1
#define G_TX_CLAMP          2
#define G_TX_NOMASK         0
#define G_TX_NOLOD          0

