#define G_CC_BLENDPEDECALA      PRIMITIVE, ENVIRONMENT, TEXEL0, ENVIRONMENT, 0, 0, 0, TEXEL0

/* ============================================================================
 * Additional GBI Macros - Dynamic (pkt++)
 * ============================================================================ */

/* DMA operation */
#define gDma1p(pkt, c, s, l, p) \
{ \
    Gfx* _g = (Gfx*)(pkt); \
    _g->words.w0 = _SHIFTL((c), 24, 8) | _SHIFTL((p), 16, 8) | _SHIFTL((l), 0, 16); \
    _g->words.w1 = (u32)(uintptr_t)(s); \
}

/* Set other mode (low and high words) */
#define gDPSetOtherMode(pkt, mode0, mode1) \
{ \
    Gfx* _g = (Gfx*)(pkt); \
    _g->words.w0 = _SHIFTL(G_RDPSETOTHERMODE, 24, 8) | (u32)(mode0); \
    _g->words.w1 = (u32)(mode1); \
}

/* Set primitive color */
#define gDPSetPrimColor(pkt, minlevel, lodfrac, r, g, b, a) \
{ \
    Gfx* _g = (Gfx*)(pkt); \
    _g->words.w0 = _SHIFTL(G_SETPRIMCOLOR, 24, 8) | _SHIFTL((minlevel), 8, 8) | _SHIFTL((lodfrac), 0, 8); \
    _g->words.w1 = _SHIFTL((r), 24, 8) | _SHIFTL((g), 16, 8) | _SHIFTL((b), 8, 8) | _SHIFTL((a), 0, 8); \
}

/* Set environment color */
#define gDPSetEnvColor(pkt, r, g, b, a) \
{ \
    Gfx* _g = (Gfx*)(pkt); \
    _g->words.w0 = _SHIFTL(G_SETENVCOLOR, 24, 8); \
    _g->words.w1 = _SHIFTL((r), 24, 8) | _SHIFTL((g), 16, 8) | _SHIFTL((b), 8, 8) | _SHIFTL((a), 0, 8); \
}

/* Set fill color */
#define gDPSetFillColor(pkt, c) \
{ \
    Gfx* _g = (Gfx*)(pkt); \
    _g->words.w0 = _SHIFTL(G_SETFILLCOLOR, 24, 8); \
    _g->words.w1 = (u32)(c); \
}

/* Fill rectangle - N64 format: 10-bit coordinates at bits 23:14 and 11:2 */
#define gDPFillRectangle(pkt, ulx, uly, lrx, lry) \
{ \
    Gfx* _g = (Gfx*)(pkt); \
    _g->words.w0 = _SHIFTL(G_FILLRECT, 24, 8) | _SHIFTL((lrx), 14, 10) | _SHIFTL((lry), 2, 10); \
    _g->words.w1 = _SHIFTL((ulx), 14, 10) | _SHIFTL((uly), 2, 10); \
}

/* Set combine mode - builds the 64-bit combine word */
#define gDPSetCombineLERP(pkt, a0, b0, c0, d0, Aa0, Ab0, Ac0, Ad0, \
                                a1, b1, c1, d1, Aa1, Ab1, Ac1, Ad1) \
{ \
    Gfx* _g = (Gfx*)(pkt); \
    _g->words.w0 = _SHIFTL(G_SETCOMBINE, 24, 8) | \
                   _SHIFTL((a0), 20, 4) | _SHIFTL((c0), 15, 5) | \
                   _SHIFTL((Aa0), 12, 3) | _SHIFTL((Ac0), 9, 3) | \
                   _SHIFTL((a1), 5, 4) | _SHIFTL((c1), 0, 5); \
    _g->words.w1 = _SHIFTL((b0), 28, 4) | _SHIFTL((b1), 24, 4) | \
                   _SHIFTL((Aa1), 21, 3) | _SHIFTL((Ac1), 18, 3) | \
                   _SHIFTL((d0), 15, 3) | _SHIFTL((Ab0), 12, 3) | \
                   _SHIFTL((Ad0), 9, 3) | _SHIFTL((d1), 6, 3) | \
                   _SHIFTL((Ab1), 3, 3) | _SHIFTL((Ad1), 0, 3); \
}

#define gDPSetCombineMode(pkt, a, b) gDPSetCombineLERP(pkt, a, b)

/* Texture rectangle - draws a textured rectangle */
#define gSPTextureRectangle(pkt, xl, yl, xh, yh, tile, s, t, dsdx, dtdy) \
{ \
    Gfx* _g0 = (Gfx*)(pkt); \
    _g0->words.w0 = _SHIFTL(G_TEXRECT, 24, 8) | _SHIFTL((xh), 12, 12) | _SHIFTL((yh), 0, 12); \
    _g0->words.w1 = _SHIFTL((tile), 24, 3) | _SHIFTL((xl), 12, 12) | _SHIFTL((yl), 0, 12); \
    Gfx* _g1 = (Gfx*)((pkt)+1); \
    _g1->words.w0 = _SHIFTL((s), 16, 16) | _SHIFTL((t), 0, 16); \
    _g1->words.w1 = _SHIFTL((dsdx), 16, 16) | _SHIFTL((dtdy), 0, 16); \
}

/* ============================================================================
 * Static GBI Macros (for static Gfx arrays)
 * ============================================================================ */

#define gsSPEndDisplayList() \
    {{ _SHIFTL(G_ENDDL, 24, 8), 0 }}

#define gsDPSetOtherMode(mode0, mode1) \
    {{ _SHIFTL(G_RDPSETOTHERMODE, 24, 8) | (u32)(mode0), (u32)(mode1) }}

#define gsDPSetCombineLERP(a0, b0, c0, d0, Aa0, Ab0, Ac0, Ad0, \
                           a1, b1, c1, d1, Aa1, Ab1, Ac1, Ad1) \
    {{ _SHIFTL(G_SETCOMBINE, 24, 8) | \
       _SHIFTL((a0), 20, 4) | _SHIFTL((c0), 15, 5) | \
       _SHIFTL((Aa0), 12, 3) | _SHIFTL((Ac0), 9, 3) | \
       _SHIFTL((a1), 5, 4) | _SHIFTL((c1), 0, 5), \
       _SHIFTL((b0), 28, 4) | _SHIFTL((b1), 24, 4) | \
       _SHIFTL((Aa1), 21, 3) | _SHIFTL((Ac1), 18, 3) | \
       _SHIFTL((d0), 15, 3) | _SHIFTL((Ab0), 12, 3) | \
       _SHIFTL((Ad0), 9, 3) | _SHIFTL((d1), 6, 3) | \
       _SHIFTL((Ab1), 3, 3) | _SHIFTL((Ad1), 0, 3) }}

