/* ============================================================================
 * Quadrangle Helper Macros (F3DEX2)
 * ============================================================================ */

#define G_QUAD  0x07

#define __gsSP1Quadrangle_w1f(v0, v1, v2, v3, flag) \
    (_SHIFTL((v0)*2, 16, 8) | _SHIFTL((v1)*2, 8, 8) | _SHIFTL((v2)*2, 0, 8))

#define __gsSP1Quadrangle_w2f(v0, v1, v2, v3, flag) \
    (_SHIFTL((v0)*2, 16, 8) | _SHIFTL((v2)*2, 8, 8) | _SHIFTL((v3)*2, 0, 8))

#define gSP1Quadrangle(pkt, v0, v1, v2, v3, flag) \
{ \
    Gfx* _g = (Gfx*)(pkt); \
    _g->words.w0 = _SHIFTL(G_TRI2, 24, 8) | __gsSP1Quadrangle_w1f(v0, v1, v2, v3, flag); \
    _g->words.w1 = __gsSP1Quadrangle_w2f(v0, v1, v2, v3, flag); \
}

#define gsSP1Quadrangle(v0, v1, v2, v3, flag) \
    {{ _SHIFTL(G_TRI2, 24, 8) | __gsSP1Quadrangle_w1f(v0, v1, v2, v3, flag), \
       __gsSP1Quadrangle_w2f(v0, v1, v2, v3, flag) }}

/* ============================================================================
 * Texture Loading Macros
 * ============================================================================ */

#define G_TX_DXT_FRAC   11

#define gDPSetTextureImage(pkt, fmt, siz, width, addr) \
{ \
    Gfx* _g = (Gfx*)(pkt); \
    _g->words.w0 = _SHIFTL(G_SETTIMG, 24, 8) | _SHIFTL((fmt), 21, 3) | \
                   _SHIFTL((siz), 19, 2) | _SHIFTL((width)-1, 0, 12); \
    _g->words.w1 = (u32)(uintptr_t)(addr); \
}

#define gDPSetTile(pkt, fmt, siz, line, tmem, tile, palette, cmt, maskt, shiftt, cms, masks, shifts) \
{ \
    Gfx* _g = (Gfx*)(pkt); \
    _g->words.w0 = _SHIFTL(G_SETTILE, 24, 8) | _SHIFTL((fmt), 21, 3) | \
                   _SHIFTL((siz), 19, 2) | _SHIFTL((line), 9, 9) | _SHIFTL((tmem), 0, 9); \
    _g->words.w1 = _SHIFTL((tile), 24, 3) | _SHIFTL((palette), 20, 4) | \
                   _SHIFTL((cmt), 18, 2) | _SHIFTL((maskt), 14, 4) | _SHIFTL((shiftt), 10, 4) | \
                   _SHIFTL((cms), 8, 2) | _SHIFTL((masks), 4, 4) | _SHIFTL((shifts), 0, 4); \
}

#define gDPLoadTile(pkt, tile, uls, ult, lrs, lrt) \
{ \
    Gfx* _g = (Gfx*)(pkt); \
    _g->words.w0 = _SHIFTL(G_LOADTILE, 24, 8) | _SHIFTL((uls), 12, 12) | _SHIFTL((ult), 0, 12); \
    _g->words.w1 = _SHIFTL((tile), 24, 3) | _SHIFTL((lrs), 12, 12) | _SHIFTL((lrt), 0, 12); \
}

#define gDPSetTileSize(pkt, tile, uls, ult, lrs, lrt) \
{ \
    Gfx* _g = (Gfx*)(pkt); \
    _g->words.w0 = _SHIFTL(G_SETTILESIZE, 24, 8) | _SHIFTL((uls), 12, 12) | _SHIFTL((ult), 0, 12); \
    _g->words.w1 = _SHIFTL((tile), 24, 3) | _SHIFTL((lrs), 12, 12) | _SHIFTL((lrt), 0, 12); \
}

#define gDPLoadTextureTile(pkt, timg, fmt, siz, width, height, \
                           uls, ult, lrs, lrt, pal, cms, cmt, masks, maskt, shifts, shiftt) \
{ \
    gDPSetTextureImage(pkt, fmt, siz, width, timg); \
    gDPSetTile(pkt, fmt, siz, (((((lrs)-(uls)+1) * (1 << (siz))) + 7) >> 3), 0, \
               G_TX_LOADTILE, 0, cmt, maskt, shiftt, cms, masks, shifts); \
    gDPLoadTile(pkt, G_TX_LOADTILE, (uls)<<2, (ult)<<2, (lrs)<<2, (lrt)<<2); \
    gDPSetTile(pkt, fmt, siz, (((((lrs)-(uls)+1) * (1 << (siz))) + 7) >> 3), 0, \
               G_TX_RENDERTILE, pal, cmt, maskt, shiftt, cms, masks, shifts); \
    gDPSetTileSize(pkt, G_TX_RENDERTILE, (uls)<<2, (ult)<<2, (lrs)<<2, (lrt)<<2); \
}

/* Simpler version - just set up for tile loading */
#define gDPLoadTextureBlock(pkt, timg, fmt, siz, width, height, pal, \
                            cms, cmt, masks, maskt, shifts, shiftt) \
    gDPLoadTextureTile(pkt, timg, fmt, siz, width, height, \
                       0, 0, (width)-1, (height)-1, pal, cms, cmt, masks, maskt, shifts, shiftt)

